ERL_NIF_TERM
libdecaf_nif_parallelhash_xof_absorb(ErlNifEnv *env, int argc, const ERL_NIF_TERM argv[])
{
    libdecaf_nif_parallelhash_ctx_t *state;
    if (argc != 2 || !enif_get_resource(env, argv[0], libdecaf_nif_parallelhash_resource_type, (void **)&state) || state->hash_mode)
        return EXCP_BADARG(env, "Expected an XOF state");
    if (state->squeezing)
        return EXCP_BADARG(env, "Cannot absorb input after squeezing has begun");
    return libdecaf_nif_parallelhash_run(env, state, enif_make_list(env, 0), argv[1], false, false, false, 0);
}

ERL_NIF_TERM
libdecaf_nif_parallelhash_xof_squeeze(ErlNifEnv *env, int argc, const ERL_NIF_TERM argv[])
{
    libdecaf_nif_parallelhash_ctx_t *state;
    unsigned long length;
    if (argc != 2 || !enif_get_resource(env, argv[0], libdecaf_nif_parallelhash_resource_type, (void **)&state) || state->hash_mode)
        return EXCP_BADARG(env, "Expected an XOF state");
    if (!enif_get_ulong(env, argv[1], &length))
        return EXCP_BADARG(env, "Length must be a non-negative byte count");
    return libdecaf_nif_parallelhash_begin_output(env, state, length, true, REDUCTIONS_UNTIL_YCF_YIELD());
}

ERL_NIF_TERM
libdecaf_nif_hash_init_parallelhash_3(ErlNifEnv *env, int argc, const ERL_NIF_TERM argv[])
{
    if (argc != 3)
        return enif_make_badarg(env);
    ERL_NIF_TERM Type = argv[0];
    ERL_NIF_TERM OutputLength = argv[1];
    ERL_NIF_TERM BlockSize = argv[2];
    libdecaf_nif_parallelhash_ctx_t state;
    decaf_bzero(&state, sizeof(state));
    ERL_NIF_TERM prefix;
    int status =
        libdecaf_nif_parallelhash_create(env, Type, true, OutputLength, true, enif_make_list(env, 0), enif_make_list(env, 0),
                                         enif_make_list(env, 0), BlockSize, enif_make_ulong(env, 0x1F), &state, &prefix);
    if (status != 1) {
        libdecaf_nif_parallelhash_destroy(&state);
        return status == 0 ? EXCP_BADARG(env, "Invalid parallelhash algorithm, length, or initialization parameters")
                           : EXCP_ERROR(env, "Can't allocate parallelhash initialization data");
    }
    ERL_NIF_TERM result =
        libdecaf_nif_parallelhash_run(env, &state, prefix, enif_make_list(env, 0), false, false, false, state.output_len);
    libdecaf_nif_parallelhash_destroy(&state);
    return result;
}
